contracts-dex/AxiomDEXAnalytics.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";

interface IAxiomExchangeHubAnalytics {
    function getPoolCore(uint256 poolId) external view returns (
        address tokenA, address tokenB, uint256 reserveA, uint256 reserveB,
        uint256 totalLiquidity, uint256 lockedLiquidity, bool isActive
    );
    function getPoolMeta(uint256 poolId) external view returns (
        uint256 createdAt, uint256 totalVolume, uint256 totalFees, uint256 poolFee
    );
    function totalPools() external view returns (uint256);
    function totalSwaps() external view returns (uint256);
    function poolFeeReserveA(uint256 poolId) external view returns (uint256);
    function poolFeeReserveB(uint256 poolId) external view returns (uint256);
}

/**
 * @title AxiomDEXAnalytics
 * @author Axiom Protocol
 * @notice On-chain analytics for DEX metrics (TVL, volume, fees)
 * @dev Aggregates data from ExchangeHub for dashboards and monitoring
 */
contract AxiomDEXAnalytics is 
    Initializable,
    AccessControlUpgradeable,
    UUPSUpgradeable
{
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");
    bytes32 public constant UPGRADER_ROLE = keccak256("UPGRADER_ROLE");

    uint256 public constant PRECISION = 1e18;

    struct DailySnapshot {
        uint256 timestamp;
        uint256 totalTVL;
        uint256 totalVolume24h;
        uint256 totalFees24h;
        uint256 activePools;
        uint256 totalSwaps;
    }

    struct PoolSnapshot {
        uint256 timestamp;
        uint256 reserveA;
        uint256 reserveB;
        uint256 totalLiquidity;
        uint256 volume24h;
        uint256 fees24h;
        uint256 apr;
    }

    struct GlobalMetrics {
        uint256 totalTVL;
        uint256 activePools;
        uint256 totalVolume24h;
        uint256 totalFees24h;
        uint256 totalSwaps;
        uint256 historicalVolume;
        uint256 historicalFees;
    }

    struct PoolMetrics {
        uint256 tvl;
        uint256 volume24h;
        uint256 fees24h;
        uint256 apr;
        uint256 reserveA;
        uint256 reserveB;
        uint256 totalLiquidity;
    }

    address public exchangeHub;
    address public treasurySafe;

    mapping(address => uint256) public tokenPrices;
    mapping(uint256 => DailySnapshot[]) public dailySnapshots;
    mapping(uint256 => mapping(uint256 => PoolSnapshot[])) public poolSnapshots;

    uint256 public lastGlobalSnapshotTime;
    uint256 public snapshotInterval;

    uint256 public totalHistoricalVolume;
    uint256 public totalHistoricalFees;

    mapping(uint256 => uint256) public poolVolumeLast24h;
    mapping(uint256 => uint256) public poolFeesLast24h;
    mapping(uint256 => uint256) public poolLastVolumeUpdate;

    event GlobalSnapshotTaken(uint256 indexed day, uint256 totalTVL, uint256 volume24h, uint256 fees24h);
    event PoolSnapshotTaken(uint256 indexed poolId, uint256 indexed day, uint256 tvl, uint256 volume24h);
    event VolumeRecorded(uint256 indexed poolId, uint256 volume, uint256 fees);
    event TokenPriceUpdated(address indexed token, uint256 price);

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() { _disableInitializers(); }

    function initialize(
        address _exchangeHub,
        address _treasurySafe
    ) public initializer {
        require(_exchangeHub != address(0) && _treasurySafe != address(0), "Zero addr");

        __AccessControl_init();
        __UUPSUpgradeable_init();

        exchangeHub = _exchangeHub;
        treasurySafe = _treasurySafe;
        snapshotInterval = 1 days;

        _grantRole(DEFAULT_ADMIN_ROLE, _treasurySafe);
        _grantRole(ADMIN_ROLE, _treasurySafe);
        _grantRole(UPGRADER_ROLE, _treasurySafe);
        _grantRole(OPERATOR_ROLE, msg.sender);
    }

    function recordSwapVolume(uint256 poolId, uint256 volume, uint256 fees) external onlyRole(OPERATOR_ROLE) {
        if (block.timestamp >= poolLastVolumeUpdate[poolId] + 24 hours) {
            poolVolumeLast24h[poolId] = 0;
            poolFeesLast24h[poolId] = 0;
        }

        poolVolumeLast24h[poolId] += volume;
        poolFeesLast24h[poolId] += fees;
        poolLastVolumeUpdate[poolId] = block.timestamp;

        totalHistoricalVolume += volume;
        totalHistoricalFees += fees;

        emit VolumeRecorded(poolId, volume, fees);
    }

    function takeGlobalSnapshot() external onlyRole(OPERATOR_ROLE) {
        require(block.timestamp >= lastGlobalSnapshotTime + snapshotInterval, "Too soon");

        uint256 day = block.timestamp / 1 days;

        (uint256 totalTVL, uint256 activePools) = _calculateTotalTVL();
        uint256 totalVolume24h = _calculateTotalVolume24h();
        uint256 totalFees24h = _calculateTotalFees24h();
        uint256 totalSwaps = IAxiomExchangeHubAnalytics(exchangeHub).totalSwaps();

        DailySnapshot memory snapshot = DailySnapshot({
            timestamp: block.timestamp,
            totalTVL: totalTVL,
            totalVolume24h: totalVolume24h,
            totalFees24h: totalFees24h,
            activePools: activePools,
            totalSwaps: totalSwaps
        });

        dailySnapshots[day].push(snapshot);
        lastGlobalSnapshotTime = block.timestamp;

        emit GlobalSnapshotTaken(day, totalTVL, totalVolume24h, totalFees24h);
    }

    function takePoolSnapshot(uint256 poolId) external onlyRole(OPERATOR_ROLE) {
        uint256 day = block.timestamp / 1 days;

        (address tokenA, address tokenB, uint256 reserveA, uint256 reserveB, 
         uint256 totalLiquidity,, bool isActive) = IAxiomExchangeHubAnalytics(exchangeHub).getPoolCore(poolId);

        require(isActive, "Pool not active");

        uint256 tvl = _calculatePoolTVL(tokenA, tokenB, reserveA, reserveB);
        uint256 volume24h = poolVolumeLast24h[poolId];
        uint256 fees24h = poolFeesLast24h[poolId];
        uint256 apr = _calculateAPR(tvl, fees24h);

        PoolSnapshot memory snapshot = PoolSnapshot({
            timestamp: block.timestamp,
            reserveA: reserveA,
            reserveB: reserveB,
            totalLiquidity: totalLiquidity,
            volume24h: volume24h,
            fees24h: fees24h,
            apr: apr
        });

        poolSnapshots[poolId][day].push(snapshot);

        emit PoolSnapshotTaken(poolId, day, tvl, volume24h);
    }

    function setTokenPrice(address token, uint256 price) external onlyRole(OPERATOR_ROLE) {
        tokenPrices[token] = price;
        emit TokenPriceUpdated(token, price);
    }

    function setTokenPrices(address[] calldata tokens, uint256[] calldata prices) external onlyRole(OPERATOR_ROLE) {
        require(tokens.length == prices.length, "Length mismatch");
        for (uint256 i = 0; i < tokens.length; i++) {
            tokenPrices[tokens[i]] = prices[i];
            emit TokenPriceUpdated(tokens[i], prices[i]);
        }
    }

    function setSnapshotInterval(uint256 interval) external onlyRole(ADMIN_ROLE) {
        snapshotInterval = interval;
    }

    function getTotalTVL() external view returns (uint256 tvl, uint256 activePools) {
        return _calculateTotalTVL();
    }

    function getPoolTVL(uint256 poolId) external view returns (uint256) {
        (address tokenA, address tokenB, uint256 reserveA, uint256 reserveB,,, bool isActive) = 
            IAxiomExchangeHubAnalytics(exchangeHub).getPoolCore(poolId);

        if (!isActive) return 0;
        return _calculatePoolTVL(tokenA, tokenB, reserveA, reserveB);
    }

    function getPoolAPR(uint256 poolId) external view returns (uint256) {
        (address tokenA, address tokenB, uint256 reserveA, uint256 reserveB,,, bool isActive) = 
            IAxiomExchangeHubAnalytics(exchangeHub).getPoolCore(poolId);

        if (!isActive) return 0;

        uint256 tvl = _calculatePoolTVL(tokenA, tokenB, reserveA, reserveB);
        uint256 fees24h = poolFeesLast24h[poolId];

        return _calculateAPR(tvl, fees24h);
    }

    function getGlobalMetrics() external view returns (GlobalMetrics memory metrics) {
        (metrics.totalTVL, metrics.activePools) = _calculateTotalTVL();
        metrics.totalVolume24h = _calculateTotalVolume24h();
        metrics.totalFees24h = _calculateTotalFees24h();
        metrics.totalSwaps = IAxiomExchangeHubAnalytics(exchangeHub).totalSwaps();
        metrics.historicalVolume = totalHistoricalVolume;
        metrics.historicalFees = totalHistoricalFees;
    }

    function getPoolMetrics(uint256 poolId) external view returns (PoolMetrics memory metrics) {
        (address tokenA, address tokenB, uint256 resA, uint256 resB, 
         uint256 liq,, bool isActive) = IAxiomExchangeHubAnalytics(exchangeHub).getPoolCore(poolId);

        if (!isActive) return metrics;

        metrics.reserveA = resA;
        metrics.reserveB = resB;
        metrics.totalLiquidity = liq;
        metrics.tvl = _calculatePoolTVL(tokenA, tokenB, resA, resB);
        metrics.volume24h = poolVolumeLast24h[poolId];
        metrics.fees24h = poolFeesLast24h[poolId];
        metrics.apr = _calculateAPR(metrics.tvl, metrics.fees24h);
    }

    function getDailySnapshots(uint256 day) external view returns (DailySnapshot[] memory) {
        return dailySnapshots[day];
    }

    function getPoolSnapshots(uint256 poolId, uint256 day) external view returns (PoolSnapshot[] memory) {
        return poolSnapshots[poolId][day];
    }

    function _calculateTotalTVL() internal view returns (uint256 totalTVL, uint256 activePools) {
        uint256 numPools = IAxiomExchangeHubAnalytics(exchangeHub).totalPools();

        for (uint256 i = 1; i <= numPools; i++) {
            (address tokenA, address tokenB, uint256 reserveA, uint256 reserveB,,, bool isActive) = 
                IAxiomExchangeHubAnalytics(exchangeHub).getPoolCore(i);

            if (isActive) {
                activePools++;
                totalTVL += _calculatePoolTVL(tokenA, tokenB, reserveA, reserveB);
            }
        }
    }

    function _calculatePoolTVL(
        address tokenA,
        address tokenB,
        uint256 reserveA,
        uint256 reserveB
    ) internal view returns (uint256) {
        uint256 priceA = tokenPrices[tokenA];
        uint256 priceB = tokenPrices[tokenB];

        uint256 valueA = priceA > 0 ? (reserveA * priceA) / PRECISION : 0;
        uint256 valueB = priceB > 0 ? (reserveB * priceB) / PRECISION : 0;

        return valueA + valueB;
    }

    function _calculateTotalVolume24h() internal view returns (uint256 total) {
        uint256 numPools = IAxiomExchangeHubAnalytics(exchangeHub).totalPools();

        for (uint256 i = 1; i <= numPools; i++) {
            if (block.timestamp < poolLastVolumeUpdate[i] + 24 hours) {
                total += poolVolumeLast24h[i];
            }
        }
    }

    function _calculateTotalFees24h() internal view returns (uint256 total) {
        uint256 numPools = IAxiomExchangeHubAnalytics(exchangeHub).totalPools();

        for (uint256 i = 1; i <= numPools; i++) {
            if (block.timestamp < poolLastVolumeUpdate[i] + 24 hours) {
                total += poolFeesLast24h[i];
            }
        }
    }

    function _calculateAPR(uint256 tvl, uint256 fees24h) internal pure returns (uint256) {
        if (tvl == 0) return 0;
        return (fees24h * 365 * PRECISION) / tvl;
    }

    function _authorizeUpgrade(address) internal override onlyRole(UPGRADER_ROLE) {}

    uint256[40] private __gap;
}

contracts-dex/AxiomDEXGovernor.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

interface IAxiomExchangeHubGov {
    function setPoolFee(uint256 poolId, uint256 newFee) external;
    function getPoolCore(uint256 poolId) external view returns (
        address tokenA, address tokenB, uint256 reserveA, uint256 reserveB,
        uint256 totalLiquidity, uint256 lockedLiquidity, bool isActive
    );
    function createPool(address tokenA, address tokenB, uint256 fee) external returns (uint256);
}

/**
 * @title AxiomDEXGovernor
 * @author Axiom Protocol
 * @notice Governance for DEX fee voting and pool whitelisting
 * @dev Token-weighted voting with proposal and execution timelock
 */
contract AxiomDEXGovernor is 
    Initializable,
    AccessControlUpgradeable,
    ReentrancyGuardUpgradeable,
    UUPSUpgradeable
{
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");
    bytes32 public constant UPGRADER_ROLE = keccak256("UPGRADER_ROLE");

    uint256 public constant BASIS_POINTS = 10000;
    uint256 public constant PRECISION = 1e18;

    enum ProposalType { FEE_CHANGE, POOL_WHITELIST, PARAMETER_CHANGE }
    enum ProposalStatus { PENDING, ACTIVE, PASSED, REJECTED, EXECUTED, CANCELLED }

    struct Proposal {
        uint256 proposalId;
        address proposer;
        ProposalType proposalType;
        string description;
        bytes data;
        uint256 votesFor;
        uint256 votesAgainst;
        uint256 startTime;
        uint256 endTime;
        uint256 executionTime;
        ProposalStatus status;
        bool executed;
    }

    struct PoolCandidate {
        address tokenA;
        address tokenB;
        uint256 proposedFee;
        uint256 proposalId;
        bool approved;
        bool created;
    }

    address public governanceToken;
    address public exchangeHub;
    address public treasurySafe;

    uint256 public proposalThreshold;
    uint256 public votingPeriod;
    uint256 public executionDelay;
    uint256 public quorumPercentage;
    uint256 public nextProposalId;
    uint256 public proposalDeposit;
    uint256 public maxActiveProposalsPerUser;

    mapping(uint256 => Proposal) public proposals;
    mapping(uint256 => mapping(address => uint256)) public proposalVotes;
    mapping(uint256 => mapping(address => bool)) public hasVoted;
    mapping(bytes32 => PoolCandidate) public poolCandidates;
    mapping(uint256 => uint256) public proposalDeposits;
    mapping(address => uint256) public activeProposalCount;

    bytes32[] public pendingPoolHashes;

    event ProposalCreated(uint256 indexed proposalId, address indexed proposer, ProposalType proposalType, string description);
    event VoteCast(uint256 indexed proposalId, address indexed voter, bool support, uint256 weight);
    event ProposalExecuted(uint256 indexed proposalId);
    event ProposalCancelled(uint256 indexed proposalId);
    event PoolCandidateProposed(bytes32 indexed poolHash, address tokenA, address tokenB, uint256 proposedFee);
    event PoolCandidateApproved(bytes32 indexed poolHash);
    event DepositRefunded(uint256 indexed proposalId, address indexed proposer, uint256 amount);

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() { _disableInitializers(); }

    function initialize(
        address _governanceToken,
        address _exchangeHub,
        address _treasurySafe,
        uint256 _proposalThreshold,
        uint256 _votingPeriod,
        uint256 _executionDelay
    ) public initializer {
        require(_governanceToken != address(0) && _exchangeHub != address(0) && _treasurySafe != address(0), "Zero addr");

        __AccessControl_init();
        __ReentrancyGuard_init();
        __UUPSUpgradeable_init();

        governanceToken = _governanceToken;
        exchangeHub = _exchangeHub;
        treasurySafe = _treasurySafe;
        proposalThreshold = _proposalThreshold;
        votingPeriod = _votingPeriod;
        executionDelay = _executionDelay;
        quorumPercentage = 400;
        nextProposalId = 1;
        proposalDeposit = _proposalThreshold / 10;
        maxActiveProposalsPerUser = 3;

        _grantRole(DEFAULT_ADMIN_ROLE, _treasurySafe);
        _grantRole(ADMIN_ROLE, _treasurySafe);
        _grantRole(UPGRADER_ROLE, _treasurySafe);
        _grantRole(OPERATOR_ROLE, msg.sender);
    }

    function proposeFeeChange(
        uint256 poolId,
        uint256 newFee,
        string calldata description
    ) external nonReentrant returns (uint256) {
        require(IERC20(governanceToken).balanceOf(msg.sender) >= proposalThreshold, "Below threshold");
        require(newFee >= 10 && newFee <= 1000, "Fee out of range");

        (,,,,,, bool isActive) = IAxiomExchangeHubGov(exchangeHub).getPoolCore(poolId);
        require(isActive, "Pool not active");

        bytes memory data = abi.encode(poolId, newFee);

        uint256 proposalId = _createProposal(ProposalType.FEE_CHANGE, description, data);

        return proposalId;
    }

    function proposePoolWhitelist(
        address tokenA,
        address tokenB,
        uint256 proposedFee,
        string calldata description
    ) external nonReentrant returns (uint256) {
        require(IERC20(governanceToken).balanceOf(msg.sender) >= proposalThreshold, "Below threshold");
        require(tokenA != address(0) && tokenB != address(0) && tokenA != tokenB, "Invalid tokens");
        require(proposedFee >= 10 && proposedFee <= 1000, "Fee out of range");

        bytes32 poolHash = keccak256(abi.encodePacked(tokenA, tokenB));
        require(!poolCandidates[poolHash].approved, "Already approved");

        bytes memory data = abi.encode(tokenA, tokenB, proposedFee);

        uint256 proposalId = _createProposal(ProposalType.POOL_WHITELIST, description, data);

        poolCandidates[poolHash] = PoolCandidate({
            tokenA: tokenA,
            tokenB: tokenB,
            proposedFee: proposedFee,
            proposalId: proposalId,
            approved: false,
            created: false
        });

        pendingPoolHashes.push(poolHash);

        emit PoolCandidateProposed(poolHash, tokenA, tokenB, proposedFee);

        return proposalId;
    }

    function _createProposal(
        ProposalType proposalType,
        string calldata description,
        bytes memory data
    ) internal returns (uint256) {
        require(activeProposalCount[msg.sender] < maxActiveProposalsPerUser, "Too many active proposals");

        if (proposalDeposit > 0) {
            IERC20(governanceToken).transferFrom(msg.sender, address(this), proposalDeposit);
        }

        uint256 proposalId = nextProposalId++;
        activeProposalCount[msg.sender]++;

        proposals[proposalId] = Proposal({
            proposalId: proposalId,
            proposer: msg.sender,
            proposalType: proposalType,
            description: description,
            data: data,
            votesFor: 0,
            votesAgainst: 0,
            startTime: block.timestamp,
            endTime: block.timestamp + votingPeriod,
            executionTime: 0,
            status: ProposalStatus.ACTIVE,
            executed: false
        });

        proposalDeposits[proposalId] = proposalDeposit;

        emit ProposalCreated(proposalId, msg.sender, proposalType, description);

        return proposalId;
    }

    function vote(uint256 proposalId, bool support) external nonReentrant {
        Proposal storage proposal = proposals[proposalId];
        require(proposal.status == ProposalStatus.ACTIVE, "Not active");
        require(block.timestamp >= proposal.startTime && block.timestamp <= proposal.endTime, "Outside voting period");
        require(!hasVoted[proposalId][msg.sender], "Already voted");

        uint256 weight = IERC20(governanceToken).balanceOf(msg.sender);
        require(weight > 0, "No voting power");

        hasVoted[proposalId][msg.sender] = true;
        proposalVotes[proposalId][msg.sender] = weight;

        if (support) {
            proposal.votesFor += weight;
        } else {
            proposal.votesAgainst += weight;
        }

        emit VoteCast(proposalId, msg.sender, support, weight);
    }

    function finalizeProposal(uint256 proposalId) external {
        Proposal storage proposal = proposals[proposalId];
        require(proposal.status == ProposalStatus.ACTIVE, "Not active");
        require(block.timestamp > proposal.endTime, "Voting not ended");

        uint256 totalSupply = IERC20(governanceToken).totalSupply();
        uint256 quorum = (totalSupply * quorumPercentage) / BASIS_POINTS;
        uint256 totalVotes = proposal.votesFor + proposal.votesAgainst;

        activeProposalCount[proposal.proposer]--;

        if (totalVotes >= quorum && proposal.votesFor > proposal.votesAgainst) {
            proposal.status = ProposalStatus.PASSED;
            proposal.executionTime = block.timestamp + executionDelay;
        } else {
            proposal.status = ProposalStatus.REJECTED;
        }

        uint256 depositAmount = proposalDeposits[proposalId];
        if (depositAmount > 0) {
            proposalDeposits[proposalId] = 0;
            IERC20(governanceToken).transfer(proposal.proposer, depositAmount);
            emit DepositRefunded(proposalId, proposal.proposer, depositAmount);
        }
    }

    function executeProposal(uint256 proposalId) external nonReentrant {
        Proposal storage proposal = proposals[proposalId];
        require(proposal.status == ProposalStatus.PASSED, "Not passed");
        require(block.timestamp >= proposal.executionTime, "Execution delay not met");
        require(!proposal.executed, "Already executed");

        proposal.executed = true;
        proposal.status = ProposalStatus.EXECUTED;

        if (proposal.proposalType == ProposalType.FEE_CHANGE) {
            (uint256 poolId, uint256 newFee) = abi.decode(proposal.data, (uint256, uint256));
            IAxiomExchangeHubGov(exchangeHub).setPoolFee(poolId, newFee);
        } else if (proposal.proposalType == ProposalType.POOL_WHITELIST) {
            (address tokenA, address tokenB, uint256 proposedFee) = abi.decode(proposal.data, (address, address, uint256));
            bytes32 poolHash = keccak256(abi.encodePacked(tokenA, tokenB));
            poolCandidates[poolHash].approved = true;
            emit PoolCandidateApproved(poolHash);
        }

        emit ProposalExecuted(proposalId);
    }

    function createApprovedPool(bytes32 poolHash) external onlyRole(OPERATOR_ROLE) returns (uint256) {
        PoolCandidate storage candidate = poolCandidates[poolHash];
        require(candidate.approved, "Not approved");
        require(!candidate.created, "Already created");

        candidate.created = true;

        return IAxiomExchangeHubGov(exchangeHub).createPool(
            candidate.tokenA,
            candidate.tokenB,
            candidate.proposedFee
        );
    }

    function cancelProposal(uint256 proposalId) external {
        Proposal storage proposal = proposals[proposalId];
        require(proposal.proposer == msg.sender || hasRole(ADMIN_ROLE, msg.sender), "Not authorized");
        require(proposal.status == ProposalStatus.ACTIVE || proposal.status == ProposalStatus.PASSED, "Cannot cancel");

        proposal.status = ProposalStatus.CANCELLED;
        activeProposalCount[proposal.proposer]--;

        uint256 depositAmount = proposalDeposits[proposalId];
        if (depositAmount > 0) {
            proposalDeposits[proposalId] = 0;
            IERC20(governanceToken).transfer(proposal.proposer, depositAmount);
            emit DepositRefunded(proposalId, proposal.proposer, depositAmount);
        }

        emit ProposalCancelled(proposalId);
    }

    function setProposalThreshold(uint256 threshold) external onlyRole(ADMIN_ROLE) {
        proposalThreshold = threshold;
    }

    function setVotingPeriod(uint256 period) external onlyRole(ADMIN_ROLE) {
        votingPeriod = period;
    }

    function setExecutionDelay(uint256 delay) external onlyRole(ADMIN_ROLE) {
        executionDelay = delay;
    }

    function setQuorumPercentage(uint256 percentage) external onlyRole(ADMIN_ROLE) {
        require(percentage <= BASIS_POINTS, "Too high");
        quorumPercentage = percentage;
    }

    function setProposalDeposit(uint256 deposit) external onlyRole(ADMIN_ROLE) {
        proposalDeposit = deposit;
    }

    function setMaxActiveProposals(uint256 max) external onlyRole(ADMIN_ROLE) {
        require(max >= 1, "Must be at least 1");
        maxActiveProposalsPerUser = max;
    }

    function getProposal(uint256 proposalId) external view returns (Proposal memory) {
        return proposals[proposalId];
    }

    function getPoolCandidate(bytes32 poolHash) external view returns (PoolCandidate memory) {
        return poolCandidates[poolHash];
    }

    function getPendingPoolHashes() external view returns (bytes32[] memory) {
        return pendingPoolHashes;
    }

    function getVotingPower(address account) external view returns (uint256) {
        return IERC20(governanceToken).balanceOf(account);
    }

    function _authorizeUpgrade(address) internal override onlyRole(UPGRADER_ROLE) {}

    uint256[40] private __gap;
}

