// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

interface IAxiomExchangeHubOrders {
    function swap(uint256 poolId, address tokenIn, uint256 amountIn, uint256 minAmountOut, uint256 deadline) external returns (uint256);
    function getAmountOut(uint256 poolId, address tokenIn, uint256 amountIn) external view returns (uint256);
    function getPoolCore(uint256 poolId) external view returns (
        address tokenA, address tokenB, uint256 reserveA, uint256 reserveB,
        uint256 totalLiquidity, uint256 lockedLiquidity, bool isActive
    );
    function pairToPoolId(address tokenA, address tokenB) external view returns (uint256);
}

interface IAxiomOracleAdapter {
    function getPrice(address token) external view returns (uint256 price, uint256 timestamp);
    function getTWAP(address token, uint256 period) external view returns (uint256);
}

/**
 * @title AxiomLimitOrders
 * @author Axiom Protocol
 * @notice On-chain limit order book with oracle price validation
 * @dev Orders are stored on-chain and executed by keepers when price conditions are met
 */
contract AxiomLimitOrders is 
    Initializable,
    AccessControlUpgradeable,
    ReentrancyGuardUpgradeable,
    PausableUpgradeable,
    UUPSUpgradeable
{
    using SafeERC20 for IERC20;

    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");
    bytes32 public constant KEEPER_ROLE = keccak256("KEEPER_ROLE");
    bytes32 public constant UPGRADER_ROLE = keccak256("UPGRADER_ROLE");

    uint256 public constant PRECISION = 1e18;
    uint256 public constant BASIS_POINTS = 10000;
    uint256 public constant MAX_ORDERS_PER_USER = 20;

    enum OrderType { LIMIT_BUY, LIMIT_SELL, STOP_LOSS, TAKE_PROFIT }
    enum OrderStatus { PENDING, FILLED, CANCELLED, EXPIRED }

    struct Order {
        uint256 orderId;
        address owner;
        uint256 poolId;
        address tokenIn;
        address tokenOut;
        uint256 amountIn;
        uint256 targetPrice;
        uint256 minAmountOut;
        OrderType orderType;
        OrderStatus status;
        uint256 createdAt;
        uint256 expiresAt;
        uint256 filledAt;
        uint256 amountReceived;
    }

    address public exchangeHub;
    address public oracleAdapter;
    address public treasurySafe;

    uint256 public nextOrderId;
    uint256 public executionFee;
    uint256 public maxPriceDeviation;
    uint256 public minOrderDuration;
    uint256 public maxOrderDuration;

    mapping(uint256 => Order) public orders;
    mapping(address => uint256[]) public userOrders;
    mapping(address => uint256) public userActiveOrderCount;

    uint256[] public pendingOrderIds;
    mapping(uint256 => uint256) public pendingOrderIndex;

    event OrderCreated(
        uint256 indexed orderId,
        address indexed owner,
        OrderType orderType,
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 targetPrice
    );
    event OrderFilled(uint256 indexed orderId, address indexed owner, uint256 amountIn, uint256 amountReceived);
    event OrderCancelled(uint256 indexed orderId, address indexed owner);
    event OrderExpired(uint256 indexed orderId);
    event ExecutionFeeUpdated(uint256 oldFee, uint256 newFee);

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() { _disableInitializers(); }

    function initialize(
        address _exchangeHub,
        address _oracleAdapter,
        address _treasurySafe,
        uint256 _executionFee
    ) public initializer {
        require(_exchangeHub != address(0) && _treasurySafe != address(0), "Zero addr");

        __AccessControl_init();
        __ReentrancyGuard_init();
        __Pausable_init();
        __UUPSUpgradeable_init();

        exchangeHub = _exchangeHub;
        oracleAdapter = _oracleAdapter;
        treasurySafe = _treasurySafe;
        executionFee = _executionFee;

        maxPriceDeviation = 500;
        minOrderDuration = 5 minutes;
        maxOrderDuration = 30 days;
        nextOrderId = 1;

        _grantRole(DEFAULT_ADMIN_ROLE, _treasurySafe);
        _grantRole(ADMIN_ROLE, _treasurySafe);
        _grantRole(UPGRADER_ROLE, _treasurySafe);
        _grantRole(OPERATOR_ROLE, msg.sender);
        _grantRole(KEEPER_ROLE, msg.sender);
    }

    function createOrder(
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 targetPrice,
        uint256 minAmountOut,
        OrderType orderType,
        uint256 duration
    ) external payable nonReentrant whenNotPaused returns (uint256) {
        require(msg.value >= executionFee, "Insufficient fee");
        require(amountIn > 0, "Zero amount");
        require(targetPrice > 0, "Zero price");
        require(duration >= minOrderDuration && duration <= maxOrderDuration, "Invalid duration");
        require(userActiveOrderCount[msg.sender] < MAX_ORDERS_PER_USER, "Too many orders");

        uint256 poolId = IAxiomExchangeHubOrders(exchangeHub).pairToPoolId(tokenIn, tokenOut);
        require(poolId > 0, "Pool not found");

        IERC20(tokenIn).safeTransferFrom(msg.sender, address(this), amountIn);

        uint256 orderId = nextOrderId++;

        orders[orderId] = Order({
            orderId: orderId,
            owner: msg.sender,
            poolId: poolId,
            tokenIn: tokenIn,
            tokenOut: tokenOut,
            amountIn: amountIn,
            targetPrice: targetPrice,
            minAmountOut: minAmountOut,
            orderType: orderType,
            status: OrderStatus.PENDING,
            createdAt: block.timestamp,
            expiresAt: block.timestamp + duration,
            filledAt: 0,
            amountReceived: 0
        });

        userOrders[msg.sender].push(orderId);
        userActiveOrderCount[msg.sender]++;

        pendingOrderIndex[orderId] = pendingOrderIds.length;
        pendingOrderIds.push(orderId);

        if (msg.value > executionFee) {
            payable(msg.sender).transfer(msg.value - executionFee);
        }

        emit OrderCreated(orderId, msg.sender, orderType, tokenIn, tokenOut, amountIn, targetPrice);

        return orderId;
    }

    function cancelOrder(uint256 orderId) external nonReentrant {
        Order storage order = orders[orderId];
        require(order.owner == msg.sender, "Not owner");
        require(order.status == OrderStatus.PENDING, "Not pending");

        order.status = OrderStatus.CANCELLED;
        userActiveOrderCount[msg.sender]--;

        _removePendingOrder(orderId);

        IERC20(order.tokenIn).safeTransfer(msg.sender, order.amountIn);

        emit OrderCancelled(orderId, msg.sender);
    }

    function executeOrder(uint256 orderId) external nonReentrant onlyRole(KEEPER_ROLE) {
        Order storage order = orders[orderId];
        require(order.status == OrderStatus.PENDING, "Not pending");

        if (block.timestamp > order.expiresAt) {
            order.status = OrderStatus.EXPIRED;
            userActiveOrderCount[order.owner]--;
            _removePendingOrder(orderId);

            IERC20(order.tokenIn).safeTransfer(order.owner, order.amountIn);
            emit OrderExpired(orderId);
            return;
        }

        require(_checkPriceCondition(order), "Price condition not met");

        IERC20(order.tokenIn).forceApprove(exchangeHub, order.amountIn);

        uint256 amountReceived = IAxiomExchangeHubOrders(exchangeHub).swap(
            order.poolId,
            order.tokenIn,
            order.amountIn,
            order.minAmountOut,
            block.timestamp + 60
        );

        order.status = OrderStatus.FILLED;
        order.filledAt = block.timestamp;
        order.amountReceived = amountReceived;
        userActiveOrderCount[order.owner]--;

        _removePendingOrder(orderId);

        IERC20(order.tokenOut).safeTransfer(order.owner, amountReceived);

        payable(msg.sender).transfer(executionFee);

        emit OrderFilled(orderId, order.owner, order.amountIn, amountReceived);
    }

    function batchExecuteOrders(uint256[] calldata orderIds) external nonReentrant onlyRole(KEEPER_ROLE) {
        uint256 executedCount = 0;

        for (uint256 i = 0; i < orderIds.length; i++) {
            Order storage order = orders[orderIds[i]];

            if (order.status != OrderStatus.PENDING) continue;

            if (block.timestamp > order.expiresAt) {
                order.status = OrderStatus.EXPIRED;
                userActiveOrderCount[order.owner]--;
                _removePendingOrder(orderIds[i]);
                IERC20(order.tokenIn).safeTransfer(order.owner, order.amountIn);
                emit OrderExpired(orderIds[i]);
                continue;
            }

            if (!_checkPriceCondition(order)) continue;

            IERC20(order.tokenIn).forceApprove(exchangeHub, order.amountIn);

            try IAxiomExchangeHubOrders(exchangeHub).swap(
                order.poolId,
                order.tokenIn,
                order.amountIn,
                order.minAmountOut,
                block.timestamp + 60
            ) returns (uint256 amountReceived) {
                order.status = OrderStatus.FILLED;
                order.filledAt = block.timestamp;
                order.amountReceived = amountReceived;
                userActiveOrderCount[order.owner]--;
                executedCount++;

                _removePendingOrder(orderIds[i]);

                IERC20(order.tokenOut).safeTransfer(order.owner, amountReceived);

                emit OrderFilled(orderIds[i], order.owner, order.amountIn, amountReceived);
            } catch {
                continue;
            }
        }

        uint256 totalFee = executionFee * executedCount;
        if (executedCount > 0 && address(this).balance >= totalFee) {
            payable(msg.sender).transfer(totalFee);
        }
    }

    function _checkPriceCondition(Order storage order) internal view returns (bool) {
        uint256 currentOutput = IAxiomExchangeHubOrders(exchangeHub).getAmountOut(
            order.poolId,
            order.tokenIn,
            order.amountIn
        );

        uint256 currentPrice = (currentOutput * PRECISION) / order.amountIn;

        if (oracleAdapter != address(0)) {
            (uint256 oraclePriceIn,) = IAxiomOracleAdapter(oracleAdapter).getPrice(order.tokenIn);
            (uint256 oraclePriceOut,) = IAxiomOracleAdapter(oracleAdapter).getPrice(order.tokenOut);

            if (oraclePriceIn > 0 && oraclePriceOut > 0) {
                uint256 oracleRatio = (oraclePriceOut * PRECISION) / oraclePriceIn;
                uint256 ammRatio = currentPrice;

                uint256 deviation = ammRatio > oracleRatio 
                    ? ((ammRatio - oracleRatio) * BASIS_POINTS) / oracleRatio
                    : ((oracleRatio - ammRatio) * BASIS_POINTS) / oracleRatio;

                if (deviation > maxPriceDeviation) {
                    return false;
                }
            }
        }

        if (order.orderType == OrderType.LIMIT_BUY || order.orderType == OrderType.TAKE_PROFIT) {
            return currentPrice >= order.targetPrice;
        } else if (order.orderType == OrderType.LIMIT_SELL || order.orderType == OrderType.STOP_LOSS) {
            return currentPrice <= order.targetPrice;
        }

        return false;
    }

    function _removePendingOrder(uint256 orderId) internal {
        uint256 index = pendingOrderIndex[orderId];
        uint256 lastIndex = pendingOrderIds.length - 1;

        if (index != lastIndex) {
            uint256 lastOrderId = pendingOrderIds[lastIndex];
            pendingOrderIds[index] = lastOrderId;
            pendingOrderIndex[lastOrderId] = index;
        }

        pendingOrderIds.pop();
        delete pendingOrderIndex[orderId];
    }

    function setExecutionFee(uint256 newFee) external onlyRole(ADMIN_ROLE) {
        emit ExecutionFeeUpdated(executionFee, newFee);
        executionFee = newFee;
    }

    function setOracleAdapter(address newOracle) external onlyRole(ADMIN_ROLE) {
        oracleAdapter = newOracle;
    }

    function setMaxPriceDeviation(uint256 deviation) external onlyRole(ADMIN_ROLE) {
        require(deviation <= 2000, "Too high");
        maxPriceDeviation = deviation;
    }

    function setOrderDurationLimits(uint256 minDuration, uint256 maxDuration) external onlyRole(ADMIN_ROLE) {
        minOrderDuration = minDuration;
        maxOrderDuration = maxDuration;
    }

    function grantKeeperRole(address keeper) external onlyRole(ADMIN_ROLE) {
        _grantRole(KEEPER_ROLE, keeper);
    }

    function pause() external onlyRole(ADMIN_ROLE) { _pause(); }
    function unpause() external onlyRole(ADMIN_ROLE) { _unpause(); }

    function getOrder(uint256 orderId) external view returns (Order memory) {
        return orders[orderId];
    }

    function getUserOrders(address user) external view returns (uint256[] memory) {
        return userOrders[user];
    }

    function getPendingOrders() external view returns (uint256[] memory) {
        return pendingOrderIds;
    }

    function getExecutableOrders(uint256 limit) external view returns (uint256[] memory) {
        uint256[] memory executable = new uint256[](limit);
        uint256 count = 0;

        for (uint256 i = 0; i < pendingOrderIds.length && count < limit; i++) {
            uint256 orderId = pendingOrderIds[i];
            Order storage order = orders[orderId];

            if (order.status == OrderStatus.PENDING && block.timestamp <= order.expiresAt) {
                if (_checkPriceCondition(order)) {
                    executable[count++] = orderId;
                }
            }
        }

        assembly { mstore(executable, count) }
        return executable;
    }

    function withdrawFees() external onlyRole(ADMIN_ROLE) {
        payable(treasurySafe).transfer(address(this).balance);
    }

    function _authorizeUpgrade(address) internal override onlyRole(UPGRADER_ROLE) {}

    receive() external payable {}

    uint256[40] private __gap;
}

contracts-dex/AxiomLPStaking.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

interface IAxiomExchangeHub {
    function getUserLiquidity(uint256 poolId, address user) external view returns (uint256);
    function getPoolCore(uint256 poolId) external view returns (
        address tokenA, address tokenB, uint256 reserveA, uint256 reserveB,
        uint256 totalLiquidity, uint256 lockedLiquidity, bool isActive
    );
}

/**
 * @title AxiomLPStaking
 * @author Axiom Protocol
 * @notice Stake LP positions to earn AXM rewards with time-locked boost tiers
 * @dev Supports 4 lock tiers: 30, 90, 180, 365 days with increasing multipliers
 */
contract AxiomLPStaking is 
    Initializable,
    AccessControlUpgradeable,
    ReentrancyGuardUpgradeable,
    PausableUpgradeable,
    UUPSUpgradeable
{
    using SafeERC20 for IERC20;

    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");
    bytes32 public constant UPGRADER_ROLE = keccak256("UPGRADER_ROLE");

    uint256 public constant BASIS_POINTS = 10000;
    uint256 public constant PRECISION = 1e18;

    enum LockTier { FLEX, TIER_30, TIER_90, TIER_180, TIER_365 }

    struct TierConfig {
        uint256 duration;
        uint256 multiplier;
        bool active;
    }

    struct StakePosition {
        uint256 poolId;
        uint256 amount;
        uint256 boostedAmount;
        uint256 stakedAt;
        uint256 lockEnd;
        LockTier tier;
        uint256 rewardDebt;
        uint256 pendingRewards;
    }

    struct PoolRewards {
        uint256 accRewardPerShare;
        uint256 lastRewardTime;
        uint256 totalStaked;
        uint256 totalBoostedStaked;
        bool active;
    }

    address public exchangeHub;
    address public rewardToken;
    address public treasurySafe;

    uint256 public rewardPerSecond;
    uint256 public totalAllocPoints;

    mapping(LockTier => TierConfig) public tierConfigs;
    mapping(uint256 => PoolRewards) public poolRewards;
    mapping(uint256 => uint256) public poolAllocPoints;
    mapping(address => mapping(uint256 => StakePosition)) public userStakes;
    mapping(address => uint256[]) public userStakedPools;

    event Staked(address indexed user, uint256 indexed poolId, uint256 amount, LockTier tier, uint256 lockEnd);
    event Unstaked(address indexed user, uint256 indexed poolId, uint256 amount);
    event RewardsClaimed(address indexed user, uint256 indexed poolId, uint256 amount);
    event EmergencyUnstaked(address indexed user, uint256 indexed poolId, uint256 amount, uint256 penalty);
    event PoolAdded(uint256 indexed poolId, uint256 allocPoints);
    event PoolUpdated(uint256 indexed poolId, uint256 allocPoints);
    event RewardRateUpdated(uint256 oldRate, uint256 newRate);

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() { _disableInitializers(); }

    function initialize(
        address _exchangeHub,
        address _rewardToken,
        address _treasurySafe,
        uint256 _rewardPerSecond
    ) public initializer {
        require(_exchangeHub != address(0) && _rewardToken != address(0) && _treasurySafe != address(0), "Zero addr");

        __AccessControl_init();
        __ReentrancyGuard_init();
        __Pausable_init();
        __UUPSUpgradeable_init();

        exchangeHub = _exchangeHub;
        rewardToken = _rewardToken;
        treasurySafe = _treasurySafe;
        rewardPerSecond = _rewardPerSecond;

        _grantRole(DEFAULT_ADMIN_ROLE, _treasurySafe);
        _grantRole(ADMIN_ROLE, _treasurySafe);
        _grantRole(UPGRADER_ROLE, _treasurySafe);
        _grantRole(OPERATOR_ROLE, msg.sender);

        tierConfigs[LockTier.FLEX] = TierConfig(0, 10000, true);
        tierConfigs[LockTier.TIER_30] = TierConfig(30 days, 12500, true);
        tierConfigs[LockTier.TIER_90] = TierConfig(90 days, 15000, true);
        tierConfigs[LockTier.TIER_180] = TierConfig(180 days, 20000, true);
        tierConfigs[LockTier.TIER_365] = TierConfig(365 days, 30000, true);
    }

    function addPool(uint256 poolId, uint256 allocPoints) external onlyRole(OPERATOR_ROLE) {
        require(!poolRewards[poolId].active, "Pool exists");

        updateAllPools();

        totalAllocPoints += allocPoints;
        poolAllocPoints[poolId] = allocPoints;
        poolRewards[poolId] = PoolRewards({
            accRewardPerShare: 0,
            lastRewardTime: block.timestamp,
            totalStaked: 0,
            totalBoostedStaked: 0,
            active: true
        });

        activePoolIds.push(poolId);

        emit PoolAdded(poolId, allocPoints);
    }

    function setPoolAllocPoints(uint256 poolId, uint256 allocPoints) external onlyRole(OPERATOR_ROLE) {
        require(poolRewards[poolId].active, "Pool not active");

        updatePool(poolId);

        totalAllocPoints = totalAllocPoints - poolAllocPoints[poolId] + allocPoints;
        poolAllocPoints[poolId] = allocPoints;

        emit PoolUpdated(poolId, allocPoints);
    }

    function stake(uint256 poolId, uint256 amount, LockTier tier) external nonReentrant whenNotPaused {
        require(amount > 0, "Zero amount");
        require(poolRewards[poolId].active, "Pool not active");
        require(tierConfigs[tier].active, "Tier not active");

        uint256 userLiq = IAxiomExchangeHub(exchangeHub).getUserLiquidity(poolId, msg.sender);
        StakePosition storage pos = userStakes[msg.sender][poolId];
        require(userLiq >= pos.amount + amount, "Insufficient LP");

        updatePool(poolId);

        if (pos.amount > 0) {
            uint256 pending = _calculatePending(poolId, msg.sender);
            pos.pendingRewards += pending;
            poolRewards[poolId].totalBoostedStaked -= pos.boostedAmount;
        } else {
            userStakedPools[msg.sender].push(poolId);
        }

        uint256 lockDuration = tierConfigs[tier].duration;
        uint256 lockEnd = lockDuration > 0 ? block.timestamp + lockDuration : 0;

        if (pos.lockEnd > lockEnd) {
            lockEnd = pos.lockEnd;
            tier = pos.tier;
        }

        uint256 newAmount = pos.amount + amount;
        uint256 newBoostedAmount = (newAmount * tierConfigs[tier].multiplier) / BASIS_POINTS;

        pos.poolId = poolId;
        pos.amount = newAmount;
        pos.boostedAmount = newBoostedAmount;
        pos.stakedAt = block.timestamp;
        pos.lockEnd = lockEnd;
        pos.tier = tier;
        pos.rewardDebt = (newBoostedAmount * poolRewards[poolId].accRewardPerShare) / PRECISION;

        poolRewards[poolId].totalStaked += amount;
        poolRewards[poolId].totalBoostedStaked += newBoostedAmount;

        emit Staked(msg.sender, poolId, amount, tier, lockEnd);
    }

    function unstake(uint256 poolId, uint256 amount) external nonReentrant {
        StakePosition storage pos = userStakes[msg.sender][poolId];
        require(pos.amount >= amount, "Insufficient stake");
        require(block.timestamp >= pos.lockEnd, "Still locked");

        updatePool(poolId);

        uint256 pending = _calculatePending(poolId, msg.sender) + pos.pendingRewards;
        pos.pendingRewards = 0;

        uint256 oldBoostedAmount = pos.boostedAmount;
        uint256 newAmount = pos.amount - amount;
        uint256 newBoostedAmount = (newAmount * tierConfigs[pos.tier].multiplier) / BASIS_POINTS;

        pos.amount = newAmount;
        pos.boostedAmount = newBoostedAmount;
        pos.rewardDebt = (newBoostedAmount * poolRewards[poolId].accRewardPerShare) / PRECISION;

        poolRewards[poolId].totalStaked -= amount;
        poolRewards[poolId].totalBoostedStaked -= (oldBoostedAmount - newBoostedAmount);

        if (pending > 0) {
            IERC20(rewardToken).safeTransfer(msg.sender, pending);
            emit RewardsClaimed(msg.sender, poolId, pending);
        }

        emit Unstaked(msg.sender, poolId, amount);
    }

    function emergencyUnstake(uint256 poolId) external nonReentrant {
        StakePosition storage pos = userStakes[msg.sender][poolId];
        require(pos.amount > 0, "No stake");

        uint256 amount = pos.amount;
        uint256 boostedAmount = pos.boostedAmount;
        uint256 penalty = 0;

        if (block.timestamp < pos.lockEnd) {
            penalty = (amount * 1000) / BASIS_POINTS;
        }

        uint256 pendingRewardsForfeited = pos.pendingRewards;

        pos.amount = 0;
        pos.boostedAmount = 0;
        pos.pendingRewards = 0;
        pos.rewardDebt = 0;
        pos.lockEnd = 0;

        poolRewards[poolId].totalStaked -= amount;
        poolRewards[poolId].totalBoostedStaked -= boostedAmount;

        emit EmergencyUnstaked(msg.sender, poolId, amount, penalty + pendingRewardsForfeited);
    }

    function claimRewards(uint256 poolId) external nonReentrant {
        StakePosition storage pos = userStakes[msg.sender][poolId];
        require(pos.amount > 0, "No stake");

        updatePool(poolId);

        uint256 pending = _calculatePending(poolId, msg.sender) + pos.pendingRewards;
        require(pending > 0, "No rewards");

        pos.pendingRewards = 0;
        pos.rewardDebt = (pos.boostedAmount * poolRewards[poolId].accRewardPerShare) / PRECISION;

        IERC20(rewardToken).safeTransfer(msg.sender, pending);

        emit RewardsClaimed(msg.sender, poolId, pending);
    }

    function claimAllRewards() external nonReentrant {
        uint256[] memory pools = userStakedPools[msg.sender];
        uint256 totalPending = 0;

        for (uint256 i = 0; i < pools.length; i++) {
            uint256 poolId = pools[i];
            StakePosition storage pos = userStakes[msg.sender][poolId];

            if (pos.amount > 0) {
                updatePool(poolId);
                uint256 pending = _calculatePending(poolId, msg.sender) + pos.pendingRewards;

                if (pending > 0) {
                    pos.pendingRewards = 0;
                    pos.rewardDebt = (pos.boostedAmount * poolRewards[poolId].accRewardPerShare) / PRECISION;
                    totalPending += pending;

                    emit RewardsClaimed(msg.sender, poolId, pending);
                }
            }
        }

        require(totalPending > 0, "No rewards");
        IERC20(rewardToken).safeTransfer(msg.sender, totalPending);
    }

    function updatePool(uint256 poolId) public {
        PoolRewards storage pool = poolRewards[poolId];
        if (block.timestamp <= pool.lastRewardTime || !pool.active) return;

        if (pool.totalBoostedStaked == 0 || totalAllocPoints == 0) {
            pool.lastRewardTime = block.timestamp;
            return;
        }

        uint256 elapsed = block.timestamp - pool.lastRewardTime;
        uint256 reward = elapsed * rewardPerSecond * poolAllocPoints[poolId] / totalAllocPoints;

        pool.accRewardPerShare += (reward * PRECISION) / pool.totalBoostedStaked;
        pool.lastRewardTime = block.timestamp;
    }

    uint256[] public activePoolIds;

    function updateAllPools() public {
        for (uint256 i = 0; i < activePoolIds.length; i++) {
            uint256 poolId = activePoolIds[i];
            if (poolRewards[poolId].active) {
                updatePool(poolId);
            }
        }
    }

    function setRewardPerSecond(uint256 newRate) external onlyRole(ADMIN_ROLE) {
        updateAllPools();
        emit RewardRateUpdated(rewardPerSecond, newRate);
        rewardPerSecond = newRate;
    }

    function setTierConfig(LockTier tier, uint256 duration, uint256 multiplier, bool active) external onlyRole(ADMIN_ROLE) {
        tierConfigs[tier] = TierConfig(duration, multiplier, active);
    }

    function pause() external onlyRole(ADMIN_ROLE) { _pause(); }
    function unpause() external onlyRole(ADMIN_ROLE) { _unpause(); }

    function pendingRewards(uint256 poolId, address user) external view returns (uint256) {
        StakePosition storage pos = userStakes[user][poolId];
        if (pos.amount == 0) return 0;

        PoolRewards storage pool = poolRewards[poolId];
        uint256 accRewardPerShare = pool.accRewardPerShare;

        if (block.timestamp > pool.lastRewardTime && pool.totalBoostedStaked > 0 && totalAllocPoints > 0) {
            uint256 elapsed = block.timestamp - pool.lastRewardTime;
            uint256 reward = elapsed * rewardPerSecond * poolAllocPoints[poolId] / totalAllocPoints;
            accRewardPerShare += (reward * PRECISION) / pool.totalBoostedStaked;
        }

        uint256 pending = (pos.boostedAmount * accRewardPerShare / PRECISION) - pos.rewardDebt;

        return pending + pos.pendingRewards;
    }

    function getUserStake(uint256 poolId, address user) external view returns (StakePosition memory) {
        return userStakes[user][poolId];
    }

    function getUserStakedPools(address user) external view returns (uint256[] memory) {
        return userStakedPools[user];
    }

    function getPoolInfo(uint256 poolId) external view returns (PoolRewards memory) {
        return poolRewards[poolId];
    }

    function getTierConfig(LockTier tier) external view returns (TierConfig memory) {
        return tierConfigs[tier];
    }

    function _calculatePending(uint256 poolId, address user) internal view returns (uint256) {
        StakePosition storage pos = userStakes[user][poolId];
        return (pos.boostedAmount * poolRewards[poolId].accRewardPerShare / PRECISION) - pos.rewardDebt;
    }

    function _authorizeUpgrade(address) internal override onlyRole(UPGRADER_ROLE) {}

    uint256[40] private __gap;
}

contracts-dex/AxiomOracleAdapter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";

interface AggregatorV3Interface {
    function decimals() external view returns (uint8);
    function description() external view returns (string memory);
    function version() external view returns (uint256);
    function getRoundData(uint80 _roundId) external view returns (
        uint80 roundId,
        int256 answer,
        uint256 startedAt,
        uint256 updatedAt,
        uint80 answeredInRound
    );
    function latestRoundData() external view returns (
        uint80 roundId,
        int256 answer,
        uint256 startedAt,
        uint256 updatedAt,
        uint80 answeredInRound
    );
}

/**
 * @title AxiomOracleAdapter
 * @author Axiom Protocol
 * @notice Chainlink oracle adapter for price feeds
 * @dev Supports multiple price feeds with staleness checks and fallback logic
 */
contract AxiomOracleAdapter is 
    Initializable,
    AccessControlUpgradeable,
    UUPSUpgradeable
{
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");
    bytes32 public constant UPGRADER_ROLE = keccak256("UPGRADER_ROLE");

    uint256 public constant PRECISION = 1e18;
    uint256 public constant MAX_STALENESS = 24 hours;

    struct PriceFeed {
        address feedAddress;
        uint8 decimals;
        uint256 heartbeat;
        bool active;
        string description;
    }

    struct TWAPData {
        uint256[] prices;
        uint256[] timestamps;
        uint256 head;
        uint256 size;
        uint256 maxSize;
    }

    address public treasurySafe;
    uint256 public defaultHeartbeat;

    mapping(address => PriceFeed) public priceFeeds;
    mapping(address => TWAPData) public twapData;
    mapping(address => uint256) public fallbackPrices;
    mapping(address => uint256) public fallbackTimestamps;

    address[] public supportedTokens;
    mapping(address => bool) public isSupported;

    event PriceFeedSet(address indexed token, address indexed feed, uint256 heartbeat);
    event PriceFeedRemoved(address indexed token);
    event FallbackPriceSet(address indexed token, uint256 price);
    event TWAPUpdated(address indexed token, uint256 price, uint256 timestamp);

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() { _disableInitializers(); }

    function initialize(address _treasurySafe) public initializer {
        require(_treasurySafe != address(0), "Zero addr");

        __AccessControl_init();
        __UUPSUpgradeable_init();

        treasurySafe = _treasurySafe;
        defaultHeartbeat = 1 hours;

        _grantRole(DEFAULT_ADMIN_ROLE, _treasurySafe);
        _grantRole(ADMIN_ROLE, _treasurySafe);
        _grantRole(UPGRADER_ROLE, _treasurySafe);
        _grantRole(OPERATOR_ROLE, msg.sender);
    }

    function setPriceFeed(
        address token,
        address feed,
        uint256 heartbeat,
        string calldata description
    ) external onlyRole(OPERATOR_ROLE) {
        require(token != address(0) && feed != address(0), "Zero addr");

        uint8 decimals = AggregatorV3Interface(feed).decimals();

        priceFeeds[token] = PriceFeed({
            feedAddress: feed,
            decimals: decimals,
            heartbeat: heartbeat > 0 ? heartbeat : defaultHeartbeat,
            active: true,
            description: description
        });

        if (!isSupported[token]) {
            supportedTokens.push(token);
            isSupported[token] = true;
        }

        twapData[token] = TWAPData({
            prices: new uint256[](24),
            timestamps: new uint256[](24),
            head: 0,
            size: 0,
            maxSize: 24
        });

        emit PriceFeedSet(token, feed, heartbeat);
    }

    function removePriceFeed(address token) external onlyRole(OPERATOR_ROLE) {
        require(priceFeeds[token].active, "Feed not active");

        priceFeeds[token].active = false;

        emit PriceFeedRemoved(token);
    }

    uint256 public minTWAPUpdateInterval;
    mapping(address => uint256) public lastTWAPUpdate;

    function setFallbackPrice(address token, uint256 price) external onlyRole(OPERATOR_ROLE) {
        fallbackPrices[token] = price;
        fallbackTimestamps[token] = block.timestamp;

        emit FallbackPriceSet(token, price);
    }

    function setMinTWAPUpdateInterval(uint256 interval) external onlyRole(ADMIN_ROLE) {
        minTWAPUpdateInterval = interval;
    }

    function getPrice(address token) external view returns (uint256 price, uint256 timestamp) {
        PriceFeed storage feed = priceFeeds[token];

        if (feed.active && feed.feedAddress != address(0)) {
            try AggregatorV3Interface(feed.feedAddress).latestRoundData() returns (
                uint80,
                int256 answer,
                uint256,
                uint256 updatedAt,
                uint80
            ) {
                if (answer > 0 && block.timestamp - updatedAt <= feed.heartbeat) {
                    price = _normalizePrice(uint256(answer), feed.decimals);
                    timestamp = updatedAt;
                    return (price, timestamp);
                }
            } catch {}
        }

        if (fallbackPrices[token] > 0 && 
            block.timestamp - fallbackTimestamps[token] <= MAX_STALENESS) {
            return (fallbackPrices[token], fallbackTimestamps[token]);
        }

        return (0, 0);
    }

    function getPriceUnsafe(address token) external view returns (uint256 price, uint256 timestamp) {
        PriceFeed storage feed = priceFeeds[token];

        if (feed.active && feed.feedAddress != address(0)) {
            try AggregatorV3Interface(feed.feedAddress).latestRoundData() returns (
                uint80,
                int256 answer,
                uint256,
                uint256 updatedAt,
                uint80
            ) {
                if (answer > 0) {
                    price = _normalizePrice(uint256(answer), feed.decimals);
                    timestamp = updatedAt;
                    return (price, timestamp);
                }
            } catch {}
        }

        return (fallbackPrices[token], fallbackTimestamps[token]);
    }

    function updateTWAP(address token) external onlyRole(OPERATOR_ROLE) {
        require(block.timestamp >= lastTWAPUpdate[token] + minTWAPUpdateInterval, "Update too frequent");

        (uint256 price, uint256 timestamp) = this.getPrice(token);
        require(price > 0, "No price");

        TWAPData storage data = twapData[token];

        data.prices[data.head] = price;
        data.timestamps[data.head] = timestamp;
        data.head = (data.head + 1) % data.maxSize;

        if (data.size < data.maxSize) {
            data.size++;
        }

        lastTWAPUpdate[token] = block.timestamp;

        emit TWAPUpdated(token, price, timestamp);
    }

    function getTWAP(address token, uint256 period) external view returns (uint256) {
        TWAPData storage data = twapData[token];

        if (data.size == 0) {
            (uint256 currentPrice,) = this.getPrice(token);
            return currentPrice;
        }

        uint256 sum = 0;
        uint256 count = 0;
        uint256 cutoff = block.timestamp > period ? block.timestamp - period : 0;

        for (uint256 i = 0; i < data.size; i++) {
            uint256 idx = (data.head + data.maxSize - 1 - i) % data.maxSize;

            if (data.timestamps[idx] >= cutoff) {
                sum += data.prices[idx];
                count++;
            } else {
                break;
            }
        }

        if (count == 0) {
            (uint256 currentPrice,) = this.getPrice(token);
            return currentPrice;
        }

        return sum / count;
    }

    function getMultiplePrices(address[] calldata tokens) external view returns (
        uint256[] memory prices,
        uint256[] memory timestamps
    ) {
        prices = new uint256[](tokens.length);
        timestamps = new uint256[](tokens.length);

        for (uint256 i = 0; i < tokens.length; i++) {
            (prices[i], timestamps[i]) = this.getPrice(tokens[i]);
        }
    }

    function isPriceValid(address token) external view returns (bool) {
        PriceFeed storage feed = priceFeeds[token];

        if (!feed.active || feed.feedAddress == address(0)) {
            return fallbackPrices[token] > 0 && 
                   block.timestamp - fallbackTimestamps[token] <= MAX_STALENESS;
        }

        try AggregatorV3Interface(feed.feedAddress).latestRoundData() returns (
            uint80,
            int256 answer,
            uint256,
            uint256 updatedAt,
            uint80
        ) {
            return answer > 0 && block.timestamp - updatedAt <= feed.heartbeat;
        } catch {
            return false;
        }
    }

    function _normalizePrice(uint256 price, uint8 decimals) internal pure returns (uint256) {
        if (decimals < 18) {
            return price * (10 ** (18 - decimals));
        } else if (decimals > 18) {
            return price / (10 ** (decimals - 18));
        }
        return price;
    }

    function setDefaultHeartbeat(uint256 heartbeat) external onlyRole(ADMIN_ROLE) {
        defaultHeartbeat = heartbeat;
    }

    function getPriceFeed(address token) external view returns (PriceFeed memory) {
        return priceFeeds[token];
    }

    function getSupportedTokens() external view returns (address[] memory) {
        return supportedTokens;
    }

    function getTWAPData(address token) external view returns (
        uint256[] memory prices,
        uint256[] memory timestamps,
        uint256 size
    ) {
        TWAPData storage data = twapData[token];
        return (data.prices, data.timestamps, data.size);
    }

    function _authorizeUpgrade(address) internal override onlyRole(UPGRADER_ROLE) {}

    uint256[40] private __gap;
}

contracts-dex/AxiomTradingRewards.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/**
 * @title AxiomTradingRewards
 * @author Axiom Protocol
 * @notice Rewards users with AXM tokens based on trading volume
 * @dev Epoch-based reward distribution with volume tracking
 */
contract AxiomTradingRewards is 
    Initializable,
    AccessControlUpgradeable,
    ReentrancyGuardUpgradeable,
    PausableUpgradeable,
    UUPSUpgradeable
{
    using SafeERC20 for IERC20;

    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");
    bytes32 public constant REPORTER_ROLE = keccak256("REPORTER_ROLE");
    bytes32 public constant UPGRADER_ROLE = keccak256("UPGRADER_ROLE");

    uint256 public constant PRECISION = 1e18;
    uint256 public constant BASIS_POINTS = 10000;

    struct Epoch {
        uint256 startTime;
        uint256 endTime;
        uint256 totalVolume;
        uint256 rewardPool;
        uint256 rewardPerVolume;
        bool finalized;
    }

    struct UserEpochData {
        uint256 volume;
        bool claimed;
    }

    struct UserStats {
        uint256 totalVolume;
        uint256 totalRewardsClaimed;
        uint256 lastTradeTime;
    }

    address public rewardToken;
    address public treasurySafe;
    address public exchangeHub;

    uint256 public currentEpoch;
    uint256 public epochDuration;
    uint256 public rewardRateBps;
    uint256 public maxRewardPerEpoch;

    mapping(uint256 => Epoch) public epochs;
    mapping(uint256 => mapping(address => UserEpochData)) public userEpochData;
    mapping(address => UserStats) public userStats;
    mapping(address => uint256[]) public userEpochs;

    event EpochStarted(uint256 indexed epochId, uint256 startTime, uint256 rewardPool);
    event EpochFinalized(uint256 indexed epochId, uint256 totalVolume, uint256 rewardPerVolume);
    event VolumeRecorded(address indexed user, uint256 indexed epochId, uint256 volume);
    event RewardsClaimed(address indexed user, uint256 indexed epochId, uint256 amount);
    event RewardRateUpdated(uint256 oldRate, uint256 newRate);

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() { _disableInitializers(); }

    function initialize(
        address _rewardToken,
        address _treasurySafe,
        address _exchangeHub,
        uint256 _epochDuration,
        uint256 _rewardRateBps,
        uint256 _maxRewardPerEpoch
    ) public initializer {
        require(_rewardToken != address(0) && _treasurySafe != address(0) && _exchangeHub != address(0), "Zero addr");

        __AccessControl_init();
        __ReentrancyGuard_init();
        __Pausable_init();
        __UUPSUpgradeable_init();

        rewardToken = _rewardToken;
        treasurySafe = _treasurySafe;
        exchangeHub = _exchangeHub;
        epochDuration = _epochDuration;
        rewardRateBps = _rewardRateBps;
        maxRewardPerEpoch = _maxRewardPerEpoch;

        _grantRole(DEFAULT_ADMIN_ROLE, _treasurySafe);
        _grantRole(ADMIN_ROLE, _treasurySafe);
        _grantRole(UPGRADER_ROLE, _treasurySafe);
        _grantRole(OPERATOR_ROLE, msg.sender);
        _grantRole(REPORTER_ROLE, _exchangeHub);
    }

    function startNewEpoch(uint256 rewardPool) external onlyRole(OPERATOR_ROLE) {
        if (currentEpoch > 0) {
            Epoch storage prevEpoch = epochs[currentEpoch];
            require(block.timestamp >= prevEpoch.endTime, "Current epoch not ended");

            if (!prevEpoch.finalized) {
                _finalizeEpoch(currentEpoch);
            }
        }

        currentEpoch++;

        if (rewardPool > 0) {
            IERC20(rewardToken).safeTransferFrom(msg.sender, address(this), rewardPool);
        }

        epochs[currentEpoch] = Epoch({
            startTime: block.timestamp,
            endTime: block.timestamp + epochDuration,
            totalVolume: 0,
            rewardPool: rewardPool,
            rewardPerVolume: 0,
            finalized: false
        });

        emit EpochStarted(currentEpoch, block.timestamp, rewardPool);
    }

    function recordVolume(address user, uint256 volume) external onlyRole(REPORTER_ROLE) {
        require(currentEpoch > 0, "No active epoch");
        Epoch storage epoch = epochs[currentEpoch];
        require(block.timestamp >= epoch.startTime && block.timestamp < epoch.endTime, "Epoch not active");
        require(!epoch.finalized, "Epoch finalized");

        UserEpochData storage userData = userEpochData[currentEpoch][user];

        if (userData.volume == 0) {
            userEpochs[user].push(currentEpoch);
        }

        userData.volume += volume;
        epoch.totalVolume += volume;

        UserStats storage stats = userStats[user];
        stats.totalVolume += volume;
        stats.lastTradeTime = block.timestamp;

        emit VolumeRecorded(user, currentEpoch, volume);
    }

    function finalizeEpoch(uint256 epochId) external onlyRole(OPERATOR_ROLE) {
        _finalizeEpoch(epochId);
    }

    function _finalizeEpoch(uint256 epochId) internal {
        Epoch storage epoch = epochs[epochId];
        require(!epoch.finalized, "Already finalized");
        require(block.timestamp >= epoch.endTime || epochId < currentEpoch, "Epoch not ended");

        epoch.finalized = true;

        if (epoch.totalVolume > 0 && epoch.rewardPool > 0) {
            epoch.rewardPerVolume = (epoch.rewardPool * PRECISION) / epoch.totalVolume;
        }

        emit EpochFinalized(epochId, epoch.totalVolume, epoch.rewardPerVolume);
    }

    function claimRewards(uint256 epochId) external nonReentrant {
        Epoch storage epoch = epochs[epochId];
        require(epoch.finalized, "Epoch not finalized");

        UserEpochData storage userData = userEpochData[epochId][msg.sender];
        require(userData.volume > 0, "No volume in epoch");
        require(!userData.claimed, "Already claimed");

        uint256 reward = (userData.volume * epoch.rewardPerVolume) / PRECISION;
        require(reward > 0, "No reward");

        userData.claimed = true;
        userStats[msg.sender].totalRewardsClaimed += reward;

        IERC20(rewardToken).safeTransfer(msg.sender, reward);

        emit RewardsClaimed(msg.sender, epochId, reward);
    }

    function claimAllRewards() external nonReentrant {
        uint256[] memory epochIds = userEpochs[msg.sender];
        uint256 totalReward = 0;

        for (uint256 i = 0; i < epochIds.length; i++) {
            uint256 epochId = epochIds[i];
            Epoch storage epoch = epochs[epochId];
            UserEpochData storage userData = userEpochData[epochId][msg.sender];

            if (epoch.finalized && !userData.claimed && userData.volume > 0) {
                uint256 reward = (userData.volume * epoch.rewardPerVolume) / PRECISION;

                if (reward > 0) {
                    userData.claimed = true;
                    totalReward += reward;
                    emit RewardsClaimed(msg.sender, epochId, reward);
                }
            }
        }

        require(totalReward > 0, "No rewards");
        userStats[msg.sender].totalRewardsClaimed += totalReward;
        IERC20(rewardToken).safeTransfer(msg.sender, totalReward);
    }

    function addRewardsToCurrentEpoch(uint256 amount) external onlyRole(OPERATOR_ROLE) {
        require(currentEpoch > 0, "No active epoch");
        Epoch storage epoch = epochs[currentEpoch];
        require(!epoch.finalized, "Epoch finalized");

        IERC20(rewardToken).safeTransferFrom(msg.sender, address(this), amount);
        epoch.rewardPool += amount;
    }

    function setRewardRate(uint256 newRate) external onlyRole(ADMIN_ROLE) {
        emit RewardRateUpdated(rewardRateBps, newRate);
        rewardRateBps = newRate;
    }

    function setEpochDuration(uint256 duration) external onlyRole(ADMIN_ROLE) {
        epochDuration = duration;
    }

    function setMaxRewardPerEpoch(uint256 max) external onlyRole(ADMIN_ROLE) {
        maxRewardPerEpoch = max;
    }

    function grantReporterRole(address reporter) external onlyRole(ADMIN_ROLE) {
        _grantRole(REPORTER_ROLE, reporter);
    }

    function pause() external onlyRole(ADMIN_ROLE) { _pause(); }
    function unpause() external onlyRole(ADMIN_ROLE) { _unpause(); }

    function pendingRewards(uint256 epochId, address user) external view returns (uint256) {
        Epoch storage epoch = epochs[epochId];
        UserEpochData storage userData = userEpochData[epochId][user];

        if (!epoch.finalized || userData.claimed || userData.volume == 0) {
            return 0;
        }

        return (userData.volume * epoch.rewardPerVolume) / PRECISION;
    }

    function estimatedRewards(address user) external view returns (uint256) {
        if (currentEpoch == 0) return 0;

        Epoch storage epoch = epochs[currentEpoch];
        UserEpochData storage userData = userEpochData[currentEpoch][user];

        if (epoch.finalized || epoch.totalVolume == 0 || userData.volume == 0) {
            return 0;
        }

        uint256 estimatedRewardPerVolume = (epoch.rewardPool * PRECISION) / epoch.totalVolume;
        return (userData.volume * estimatedRewardPerVolume) / PRECISION;
    }

    function getEpoch(uint256 epochId) external view returns (Epoch memory) {
        return epochs[epochId];
    }

    function getUserStats(address user) external view returns (UserStats memory) {
        return userStats[user];
    }

    function getUserEpochData(uint256 epochId, address user) external view returns (UserEpochData memory) {
        return userEpochData[epochId][user];
    }

    function getUserEpochs(address user) external view returns (uint256[] memory) {
        return userEpochs[user];
    }

    function getCurrentEpochInfo() external view returns (Epoch memory) {
        return epochs[currentEpoch];
    }

    function _authorizeUpgrade(address) internal override onlyRole(UPGRADER_ROLE) {}

    uint256[40] private __gap;
}

